using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;
using System.Xml.Linq;
using AlibreAddOnManager;
using AlibreAddOnManager.Models;
using AlibreCatalogManager.Catalog;

namespace AlibreCatalogManager.Publishing
{
    /// <summary>
    /// An add-on project on disk, as generated by the New Add-On tab: a .csproj
    /// (C#) or .vcxproj (C++) with addon.json and the .adc beside it, and for C#
    /// Properties\AssemblyInfo.cs.
    /// A project with no addon.json gets one built from its .adc.
    /// </summary>
    public sealed class AddOnProject
    {
        public static readonly Regex VersionFormat = new Regex(@"^\d+\.\d+\.\d+$");

        // "version" only — "schemaVersion" has a different key, so it never matches.
        private static readonly Regex ManifestVersion = new Regex(@"(""version""\s*:\s*"")[^""]*("")");

        private static readonly Regex AssemblyVersions = new Regex(@"(\[assembly:\s*Assembly(?:File)?Version\(\s*"")[^""]*(""\s*\)\])");

        // FileVersion before Version: it is the one Windows shows for the DLL.
        private static readonly Regex AssemblyVersionValue =
            new Regex(@"\[assembly:\s*Assembly(?:File)?Version\(\s*""(\d+\.\d+\.\d+)(?:\.\d+)?""\s*\)\]", RegexOptions.RightToLeft);

        private AddOnProject()
        {
        }

        public string ProjectFile { get; private set; }

        public string Folder { get; private set; }

        /// <summary>The source addon.json (not the copy in the build output).</summary>
        public string ManifestPath { get; private set; }

        public PackageManifest Manifest { get; private set; }

        /// <summary>True if addon.json was missing and <see cref="Load"/> built it from the .adc.</summary>
        public bool ManifestCreated { get; private set; }

        public string AssemblyInfoPath => Path.Combine(Folder, "Properties", "AssemblyInfo.cs");

        /// <summary>A C++ project, which builds a native DLL.</summary>
        public bool IsNative => ProjectFile.EndsWith(".vcxproj", StringComparison.OrdinalIgnoreCase);

        public static AddOnProject Load(string projectFile)
        {
            var path = Path.GetFullPath(projectFile);
            if (!File.Exists(path)) throw new FileNotFoundException("Project file not found.", path);

            var project = new AddOnProject
            {
                ProjectFile = path,
                Folder = Path.GetDirectoryName(path),
                ManifestPath = Path.Combine(Path.GetDirectoryName(path), Packages.ManifestEntry)
            };

            if (!File.Exists(project.ManifestPath))
            {
                // Built from the project's .adc; the DLL may not exist yet, so the
                // version comes from AssemblyInfo.cs and the arch from the project.
                AddOnManifestFactory.WriteFromAdc(project.Folder, project.AssemblyVersion() ?? AddOnManifestFactory.DefaultVersion, project.PlatformArch());
                project.ManifestCreated = true;
            }

            var manifest = Json.ReadFile<PackageManifest>(project.ManifestPath);
            if (!Guid.TryParse(manifest.Id, out _))
                throw new InvalidOperationException($"{Packages.ManifestEntry} has no valid 'id'.");
            if (!ManagerPaths.IsValidFolderName(manifest.FolderName))
                throw new InvalidOperationException($"{Packages.ManifestEntry} needs a plain 'folderName'.");

            project.Manifest = manifest;
            return project;
        }

        /// <summary>
        /// Copies the project's addon.json into the build output, which is then packed.
        /// The project's copy is the source of truth: it carries the version just set,
        /// and a project whose addon.json was created here does not copy it on build.
        /// </summary>
        public string PrepareOutput(string configuration)
        {
            var output = OutputFolder(configuration);
            if (!Directory.Exists(output))
                throw new InvalidOperationException($"{output} does not exist — build the project first.");
            File.Copy(ManifestPath, Path.Combine(output, Packages.ManifestEntry), true);
            return output;
        }

        /// <summary>major.minor.patch from AssemblyFileVersion / AssemblyVersion, or null.</summary>
        private string AssemblyVersion()
        {
            if (!File.Exists(AssemblyInfoPath)) return null;
            var match = AssemblyVersionValue.Match(File.ReadAllText(AssemblyInfoPath));
            return match.Success ? match.Groups[1].Value : null;
        }

        /// <summary>The add-on arch implied by the project's PlatformTarget, or null.</summary>
        private string PlatformArch()
        {
            // A C++ add-on project only has x64 configurations.
            if (IsNative) return "x64";

            try
            {
                var target = XDocument.Load(ProjectFile).Descendants().FirstOrDefault(e => e.Name.LocalName == "PlatformTarget")?.Value.Trim();
                if (string.Equals(target, "x64", StringComparison.OrdinalIgnoreCase)) return "x64";
                if (string.Equals(target, "AnyCPU", StringComparison.OrdinalIgnoreCase)) return "anycpu";
            }
            catch (Exception)
            {
                // Unreadable project: leave arch out.
            }

            return null;
        }

        /// <summary>
        /// The build output folder for a configuration: the OutputPath of the
        /// matching PropertyGroup (or an unconditional one), else bin\&lt;configuration&gt;.
        /// </summary>
        public string OutputFolder(string configuration)
        {
            string outputPath = null;
            try
            {
                var groups = XDocument.Load(ProjectFile).Root?.Elements().Where(e => e.Name.LocalName == "PropertyGroup").ToList();
                foreach (var group in groups ?? Enumerable.Empty<XElement>())
                {
                    var value = group.Elements().FirstOrDefault(e => e.Name.LocalName == "OutputPath")?.Value;
                    if (string.IsNullOrWhiteSpace(value) || value.Contains("$(")) continue;
                    var condition = (string) group.Attribute("Condition");
                    if (condition == null)
                        outputPath = outputPath ?? value;
                    else if (condition.IndexOf("'" + configuration + "|", StringComparison.OrdinalIgnoreCase) >= 0 ||
                             condition.IndexOf("'" + configuration + "'", StringComparison.OrdinalIgnoreCase) >= 0)
                    {
                        outputPath = value;
                        break;
                    }
                }
            }
            catch (Exception)
            {
                // An unreadable project falls back to the convention.
            }

            return Path.GetFullPath(Path.Combine(Folder, outputPath ?? Path.Combine("bin", configuration)));
        }

        /// <summary>
        /// Sets the version in addon.json and, if present, AssemblyInfo.cs
        /// (as major.minor.patch.0). Edits the text in place to keep the layout.
        /// </summary>
        public void SetVersion(string version)
        {
            if (!VersionFormat.IsMatch(version ?? string.Empty))
                throw new ArgumentException("The version must be major.minor.patch, e.g. 1.2.0.");

            var manifestText = ReadText(ManifestPath, out var manifestBom);
            if (ManifestVersion.Matches(manifestText).Count != 1)
                throw new InvalidOperationException($"Cannot find a single \"version\" in {Packages.ManifestEntry}; edit it by hand.");
            var updatedManifest = ManifestVersion.Replace(manifestText, "${1}" + version + "${2}");

            string updatedInfo = null;
            var infoBom = false;
            if (File.Exists(AssemblyInfoPath))
            {
                var info = ReadText(AssemblyInfoPath, out infoBom);
                updatedInfo = AssemblyVersions.Replace(info, "${1}" + version + ".0${2}");
            }

            File.WriteAllText(ManifestPath, updatedManifest, new UTF8Encoding(manifestBom));
            if (updatedInfo != null) File.WriteAllText(AssemblyInfoPath, updatedInfo, new UTF8Encoding(infoBom));
            Manifest.Version = version;
        }

        private static string ReadText(string path, out bool hasBom)
        {
            var bytes = File.ReadAllBytes(path);
            hasBom = bytes.Length >= 3 && bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF;
            return new UTF8Encoding(false).GetString(bytes, hasBom ? 3 : 0, bytes.Length - (hasBom ? 3 : 0));
        }
    }
}
